function transform(occurrence, editor, file) {
  setTimeout(() => {
    const cursor = editor.getCursor();

    // Find the line containing [Dev]:
    for (let line = cursor.line; line >= 0; line--) {
      const text = editor.getLine(line);
      const devIndex = text.indexOf("[Dev]: ");

      if (devIndex !== -1) {
        // Put cursor immediately after "[Dev]: "
        editor.setCursor({
          line: line,
          ch: devIndex + 7
        });

        break;
      }
    }
  }, 10);

  return '<div class="char-devnote">\n[Dev]: \n\n</div>';
}

function transform(occurrence, editor, file) {
  setTimeout(() => {
    const cursor = editor.getCursor();
    const line = editor.getLine(cursor.line);

    const openParen = line.lastIndexOf("()", cursor.ch);

    if (openParen !== -1) {
      editor.setCursor({
        line: cursor.line,
        ch: openParen + 1
      });
    }
  }, 10);

  return '<span class="narrator">()</span>';
}

function transform(occurrence, editor, file) {
  var uid = 'LINKPICK_' + Date.now().toString(36) + Math.floor(Math.random() * 1296).toString(36);
  var placeholder = '<a href="obsidian://open?vault=PENDING&file=' + uid + '">Picking…</a>';
  try {
    var orig = '';
    try { orig = occurrence.original || ((occurrence.match && occurrence.match[0]) || ''); } catch (e0) {}
    if (orig && orig.indexOf('!link') === -1) return placeholder;
  } catch (e00) {}
  setTimeout(function () {
    try {
      var g = (typeof window !== 'undefined' && window) || globalThis;
      var doc = (g && g.document) || null;
      var appRef = (g && g.app) || null;
      if (!appRef || !doc) return;
      var vaultName = 'Lore';
      try { vaultName = appRef.vault.getName(); } catch (e) {}
      var mdFiles = [];
      try { mdFiles = appRef.vault.getMarkdownFiles(); } catch (e2) {}
      if (!mdFiles || mdFiles.length === 0) return;
      var replaceUid = function (finalTag) {
        try {
          var val = editor.getValue();
          var idx = val.indexOf(uid);
          if (idx === -1) return false;
          var start = val.lastIndexOf('<a ', idx);
          var closeTag = '</a>';
          var endIdx = val.indexOf(closeTag, idx);
          if (start === -1 || endIdx === -1) return false;
          endIdx += closeTag.length;
          var from = editor.offsetToPos(start);
          var to = editor.offsetToPos(endIdx);
          editor.replaceRange(finalTag, from, to);
          try { editor.setCursor(editor.offsetToPos(start + finalTag.length)); } catch (e5) {}
          return true;
        } catch (e6) { return false; }
      };
      var buildTag = function (chosen) {
        var rel = chosen.path.replace(/\.md$/i, '');
        var encFile = encodeURIComponent(rel);
        var encVault = encodeURIComponent(vaultName);
        return '<a href="obsidian://open?vault=' + encVault + '&file=' + encFile + '">' + chosen.basename + '</a>';
      };
      try { var stale = doc.querySelector('.linkpick-overlay'); if (stale) stale.remove(); } catch (e9) {}
      var overlay = doc.createElement('div');
      overlay.className = 'linkpick-overlay';
      overlay.setAttribute('style', 'position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,0.45);display:flex;align-items:flex-start;justify-content:center;padding-top:12vh;');
      var box = doc.createElement('div');
      box.setAttribute('style', 'background:var(--background-primary,#fff);color:var(--text-normal,#000);border:1px solid var(--background-modifier-border,#ccc);border-radius:8px;width:min(560px,90vw);max-height:60vh;display:flex;flex-direction:column;box-shadow:0 8px 32px rgba(0,0,0,0.35);');
      var input = doc.createElement('input');
      input.type = 'text';
      input.placeholder = 'Pick a note to link… (Esc cancels)';
      input.setAttribute('style', 'margin:8px;padding:8px 10px;font-size:14px;border:1px solid var(--background-modifier-border,#ccc);border-radius:6px;background:var(--background-primary,#fff);color:inherit;outline:none;');
      var list = doc.createElement('div');
      list.setAttribute('style', 'overflow-y:auto;margin:0 8px 8px 8px;');
      box.appendChild(input);
      box.appendChild(list);
      overlay.appendChild(box);
      var selected = 0;
      var filtered = [];
      var render = function () {
        while (list.firstChild) list.removeChild(list.firstChild);
        var q = input.value.toLowerCase();
        filtered = mdFiles.filter(function (f) { return f.path.toLowerCase().indexOf(q) !== -1; }).slice(0, 50);
        if (selected >= filtered.length) selected = 0;
        if (filtered.length === 0) {
          var none = doc.createElement('div');
          none.textContent = 'No matches';
          none.setAttribute('style', 'padding:6px 8px;font-size:13px;opacity:0.6;');
          list.appendChild(none);
          return;
        }
        filtered.forEach(function (f, i) {
          var item = doc.createElement('div');
          item.textContent = f.path;
          item.setAttribute('style', 'padding:6px 8px;border-radius:4px;cursor:pointer;font-size:13px;' + (i === selected ? 'background:var(--text-selection,rgba(80,140,255,0.35));' : ''));
          item.addEventListener('click', function () { cleanup(); replaceUid(buildTag(f)); });
          item.addEventListener('mousemove', function () { if (selected !== i) { selected = i; render(); } });
          list.appendChild(item);
        });
      };
      var cleanup = function () { try { overlay.remove(); } catch (e8) {} };
      input.addEventListener('input', function () { selected = 0; render(); });
      input.addEventListener('keydown', function (ev) {
        if (ev.key === 'Escape') { ev.stopPropagation(); cleanup(); }
        else if (ev.key === 'ArrowDown') { ev.preventDefault(); if (selected < filtered.length - 1) selected++; render(); }
        else if (ev.key === 'ArrowUp') { ev.preventDefault(); if (selected > 0) selected--; render(); }
        else if (ev.key === 'Enter') { ev.preventDefault(); if (filtered[selected]) { var ff = filtered[selected]; cleanup(); replaceUid(buildTag(ff)); } }
      });
      overlay.addEventListener('mousedown', function (ev) { if (ev.target === overlay) cleanup(); });
      doc.body.appendChild(overlay);
      render();
      setTimeout(function () { try { input.focus(); } catch (e7) {} }, 30);
    } catch (err) {}
  }, 10);
  return placeholder;
}

function transform(occurrence, editor, file) {
  var raw = '';
  try { raw = occurrence.original || ((occurrence.match && occurrence.match[0]) || ''); } catch (e0) {}
  var m = null;
  try { m = /!hex\s+#([0-9a-fA-F]{6})/.exec(raw); } catch (e1) {}
  // Settings-UI validation calls with mock data: leave text untouched.
  if (!m) return raw;
  var hex = '#' + m[1].toUpperCase();
  var cursorTag = 'HEXCUR_' + Date.now().toString(36);
  var out = '<span class="hexchip" style="--hex:' + hex + '"></span>' + hex + ' ' + cursorTag;
  setTimeout(function () {
    try {
      var val = editor.getValue();
      var idx = val.indexOf(cursorTag);
      if (idx === -1) return;
      var from = editor.offsetToPos(idx);
      var to = editor.offsetToPos(idx + cursorTag.length);
      editor.replaceRange('', from, to);
      try { editor.setCursor(editor.offsetToPos(idx)); } catch (e2) {}
    } catch (err) {}
  }, 10);
  return out;
}
